WITH enriched AS (SELECT id, starts_on, ends_on, discount_pct, MIN(discount_pct) OVER (PARTITION BY promo_code ORDER BY ends_on, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_min_discount_pct, SUM(discount_pct) OVER (PARTITION BY promo_code ORDER BY ends_on, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_sum_discount_pct, MAX(discount_pct) OVER (PARTITION BY promo_code ORDER BY ends_on, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_max_discount_pct FROM promotions) SELECT DATE_TRUNC('QUARTER', ends_on) AS quarter_start, CASE WHEN last4_sum_discount_pct >= 1.37 THEN 'PREMIUM' ELSE 'STANDARD' END AS last4_sum_discount_pct_tier, ROUND(AVG(last4_max_discount_pct), 2) AS avg_last4_max_discount_pct, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS num_rows, PERCENT_RANK() OVER (PARTITION BY DATE_TRUNC('QUARTER', ends_on) ORDER BY COUNT(*) DESC) AS num_rows_percent_rank FROM enriched GROUP BY quarter_start, last4_sum_discount_pct_tier;
